pair A, B, C, D, O;

A = (1,0);
B = (0,0);
C = intersectionpoint(arc(A,0.3,0,180),arc(B,0.3,0,180));
D = intersectionpoint(arc(A,0.3,180,360),arc(B,0.3,180,360));
O = (A + B)/2;

draw(A--B);
